const TAG_NAMES = { lake: '물가', canal: '운하', tide: '해안', garden: '정원', fireflies: '반딧불 서식지', lantern: '등불 풍경', festival: '조용한 축제', snow: '설경', north: '북쪽', reeds: '갈대', muhly: '풀밭', meadow: '초원', wind: '바람', fog: '안개', hills: '언덕', mountain: '산', cloud: '구름', dawn: '새벽', balloon: '넓은 새벽', rain: '비', leaves: '나무', butterfly: '꽃밭', 'aurora-sky': '천체 없는 하늘', 'open-sky': '넓은 하늘' };
